package com.fongmi.android.tv.bean;import java.util.*;public class Group{public String name="Group";public List<Channel> channels=new ArrayList<>();int position;public static Group create(int id){Group g=new Group();g.name="Keep";return g;}public String getName(){return name;}public List<Channel> getChannel(){return channels;}public boolean isEmpty(){return channels.isEmpty();}public boolean isKeep(){return name.equals("Keep");}public boolean skip(){return false;}public int getPosition(){return position;}public void setPosition(int p){position=p;}public Channel current(){return channels.get(position);} }
